+// 16 bit integer valid for add sub immediate
+operand immSAddSub()
+%{
+  predicate(n->get_int() <= 4095 && n->get_int() >= -4095);
+  match(ConI);
+
+  op_cost(0);
+  format %{ %}
+  interface(CONST_INTER);
+%}
+

